use callisto_graph::locate::LocateError;
use callisto_graph::{ConfigError, GraphError};
use callisto_model::CommandError;
use miette::Diagnostic;

/// Formats a [`CliError`] as a JSON value with a consistent error envelope:
///
/// ```json
/// {
///   "schemaVersion": 1,
///   "command": "add",
///   "dryRun": false,
///   "error": {
///     "code": "E211",
///     "message": "human-readable error text",
///     "help": "optional guidance string or null",
///     "path": "optional filesystem path or null"
///   }
/// }
/// ```
///
/// `command` is the one the command's success report carries, with the subcommand for `release plan`,
/// `release-pr verify` and the like (see [`crate::cli::Command::report_name`]), and `dryRun` is `--dry-run`.
/// Both come from the parsed arguments, not derived from the error itself --
/// an error can occur before enough context exists to reconstruct it any
/// other way (e.g. an argument-parsing failure).
///
/// `"code"`, `"message"`, `"help"`, and `"path"` are always present;
/// `"help"`/`"path"` are `null` when the diagnostic provides none. This
/// guarantees a stable shape regardless of which [`CliError`] variant is
/// serialized.
pub fn format_error_json(command: &str, dry_run: bool, err: &CliError) -> serde_json::Value {
    let code = err.code().map(|c| c.to_string()).unwrap_or_else(|| "E000".to_string());
    let help = err.help().map(|h| h.to_string());
    let path = err.path().map(|p| p.display().to_string());
    serde_json::json!({
        "schemaVersion": callisto_model::SCHEMA_VERSION,
        "command": command,
        "dryRun": dry_run,
        "error": {
            "code": code,
            "message": err.to_string(),
            "help": help,
            "path": path,
        }
    })
}

/// Codes for a bad or missing flag or argument value, or a bad flag combination, caught after parsing. These exit 2.
/// Every other code exits 1. `tests/usage_exit_codes_tests.rs` fails when a code in docs/errors.md is in neither list.
pub const USAGE_CODES: &[&str] = &[
    "E195", "E196", "E214", "E216", "E217", "E218", "E224", "E225", "E226", "E227", "E228", "E229", "E231", "E240",
    "E241", "E242", "E270", "E271", "E274", "E275", "E276", "E279", "E282", "E283", "E298", "E309", "E324", "E327",
    "E329",
];

/// Codes that are usage errors only when the offending reference came from a flag (context `--package`).
/// The same codes from `callisto.toml` content are runtime errors.
pub const USAGE_WHEN_FROM_FLAG_CODES: &[&str] = &["E316", "E317"];

impl CliError {
    /// True when the command line input was wrong or incomplete, as opposed to workspace, config, git or registry state.
    pub fn is_usage_error(&self) -> bool {
        let Some(code) = self.code().map(|c| c.to_string()) else {
            return false;
        };
        if USAGE_CODES.contains(&code.as_str()) {
            return true;
        }
        let config = match self {
            Self::Config(config) | Self::Graph(GraphError::Config(config)) => config,
            _ => return false,
        };
        match config {
            ConfigError::BareReference { context, .. } | ConfigError::ColonReference { context, .. } => {
                context.starts_with("--")
            }
            _ => false,
        }
    }
}

#[derive(Debug, thiserror::Error, Diagnostic)]
#[non_exhaustive]
pub enum CliError {
    #[error(transparent)]
    #[diagnostic(transparent)]
    Graph(#[from] GraphError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    Locate(#[from] LocateError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    Config(#[from] ConfigError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    Command(#[from] CommandError),

    #[error(transparent)]
    #[diagnostic(
        code(E211),
        help("verify registry credentials/authentication and network connectivity, then retry")
    )]
    Registry(#[from] callisto_model::RegistryError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    ChangesetParse(#[from] callisto_model::format::ParseError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    ChangesetWrite(#[from] callisto_model::format::WriteError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    Manifest(#[from] callisto_model::ManifestError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    Vcs(#[from] callisto_model::vcs::VcsError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    ReleasePrDecision(#[from] callisto_model::ReleasePrDecisionError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    ReleaseIntent(#[from] callisto_model::ReleaseIntentError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    Model(#[from] callisto_model::ModelError),

    #[error("interactive prompt failed: {0}")]
    #[diagnostic(
        code(E269),
        help("pass flags explicitly to skip interactive prompts, or run in a terminal")
